+        <div class="col"><div class="card text-center p-2"><strong>To Do</strong><span>@TodoTasks.Count</span></div></div>
+        <div class="col"><div class="card text-center p-2"><strong>In Progress</strong><span>@InProgressTasks.Count</span></div></div>
+        <div class="col"><div class="card text-center p-2"><strong>Done</strong><span>@DoneTasks.Count</span></div></div>
+        <div class="col"><div class="card text-center p-2 @(OverdueCount > 0 ? "border-danger text-danger" : "")"><strong>Overdue</strong><span>@OverdueCount</span></div></div>
+    </div>
+
+    <!-- Search -->
+    <div class="mb-3">
+        <input type="text" class="form-control" placeholder="Search tasks by title…" @bind="_searchText" @bind:event="oninput" />
+    </div>
+
+    <!-- Columns -->
+    <div class="row g-3">
+        @foreach (var col in _columns)
+        {
+            var tasks = GetFilteredTasks(col.Status);
+            var colIndex = Array.IndexOf(_columns, col);
+            <div class="col-md-4">
+                <div class="card">
+                    <div class="card-header d-flex justify-content-between align-items-center">
+                        <strong>@col.Title</strong>
+                        <span class="badge bg-secondary">@tasks.Count</span>
+                    </div>
+                    <div class="card-body p-2" style="min-height:200px;">
+                        @foreach (var task in tasks)
+                        {
+                            <div class="card mb-2">
+                                <div class="card-body p-2">
+                                    <h6 class="card-title mb-1">@task.Title</h6>
+                                    <p class="mb-1 text-muted small">@task.Assignee</p>
+                                    <span class="badge @GetPriorityClass(task.Priority) me-1">@task.Priority</span>
+                                    <span class="small text-muted">@task.DueDate.ToString("MMM dd")</span>
+                                    <div class="mt-2 d-flex gap-1">
+                                        @if (colIndex > 0)
+                                        {
+                                            <button class="btn btn-sm btn-outline-secondary" disabled="@_moving" @onclick="() => MoveTaskAsync(task.Id, _columns[colIndex - 1].Status)">← Move Left</button>
+                                        }
+                                        @if (colIndex < _columns.Length - 1)
+                                        {
+                                            <button class="btn btn-sm btn-outline-secondary" disabled="@_moving" @onclick="() => MoveTaskAsync(task.Id, _columns[colIndex + 1].Status)">Move Right →</button>
+                                        }
+                                    </div>
+                                </div>
+                            </div>
+                        }
+
+                        @if (_showForm == col.Status)
+                        {
+                            <div class="card border-primary mb-2">
+                                <div class="card-body p-2">
+                                    <input type="text" class="form-control form-control-sm mb-1" placeholder="Title" @bind="_newTitle" />
+                                    <input type="text" class="form-control form-control-sm mb-1" placeholder="Assignee" @bind="_newAssignee" />
+                                    <select class="form-select form-select-sm mb-1" @bind="_newPriority">
+                                        <option value="High">High</option>
+                                        <option value="Medium">Medium</option>
+                                        <option value="Low">Low</option>
+                                    </select>
+                                    <input type="date" class="form-control form-control-sm mb-2" @bind="_newDueDate" />
+                                    <div class="d-flex gap-1">
+                                        <button class="btn btn-sm btn-primary" disabled="@_saving" @onclick="() => SaveTaskAsync(col.Status)">Save</button>
+                                        <button class="btn btn-sm btn-outline-secondary" @onclick="CancelForm">Cancel</button>
+                                    </div>
+                                </div>
+                            </div>
+                        }
+                    </div>
+                    <div class="card-footer p-2">
+                        <button class="btn btn-sm btn-outline-primary w-100" @onclick="() => ShowAddForm(col.Status)">+ Add Task</button>
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private readonly record struct Column(string Title, string Status);
+
+    private readonly Column[] _columns =
+    [
+        new("To Do", "To Do"),
+        new("In Progress", "In Progress"),
+        new("Done", "Done")
+    ];
+
+    private List<TaskItem> _allTasks = [];
+    private bool _loading = true;
+    private string? _error;
+    private string _searchText = string.Empty;
+    private bool _moving;
+
+    // Add-task form state
+    private string? _showForm;
+    private string _newTitle = string.Empty;
+    private string _newAssignee = string.Empty;
+    private string _newPriority = "Medium";
+    private DateTime _newDueDate = DateTime.Today.AddDays(7);
+    private bool _saving;
+
+    private List<TaskItem> TodoTasks => _allTasks.Where(t => t.Status == "To Do").ToList();
+    private List<TaskItem> InProgressTasks => _allTasks.Where(t => t.Status == "In Progress").ToList();
+    private List<TaskItem> DoneTasks => _allTasks.Where(t => t.Status == "Done").ToList();
+    private int OverdueCount => _allTasks.Count(t => t.DueDate.Date < DateTime.Today && t.Status != "Done");
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasksAsync();
+    }
+
+    private async Task LoadTasksAsync()
+    {
+        _loading = true;
+        _error = null;
+
+        try
+        {
+            _allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private List<TaskItem> GetFilteredTasks(string status)
+    {
+        return _allTasks
+            .Where(t => t.Status == status &&
+                        (string.IsNullOrWhiteSpace(_searchText) ||
+                         t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)))
+            .ToList();
+    }
+
+    private async Task MoveTaskAsync(int taskId, string newStatus)
+    {
+        _moving = true;
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = _allTasks.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                _allTasks[idx] = _allTasks[idx] with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _moving = false;
+        }
+    }
+
+    private void ShowAddForm(string status)
+    {
+        _showForm = status;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = "Medium";
+        _newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelForm() => _showForm = null;
+
+    private async Task SaveTaskAsync(string status)
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle))
+            return;
+
+        _saving = true;
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(_newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);
+            // CreateTaskAsync returns the task; move it to the target column if needed
+            var task = created.Status == status ? created : created with { Status = status };
+            if (task.Status != created.Status)
+            {
+                await TaskService.UpdateTaskStatusAsync(task.Id, status);
+            }
+            _allTasks.Add(task);
+            _showForm = null;
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+
+    private static string GetPriorityClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary"
+    };
+}
+

